// AI 결과를 파싱하되 후보 누락·URL 환각을 차단하고 웹페이지 구조로 변환
const base=$('A4c. Code - 후보 병합 + 편집 프롬프트 조립').first().json;
const raw=$json.text || $json.output || $json.response || $json.content || $json.result || '';
function txt(v){return v===null||v===undefined?'':String(v).trim();}
function arr(v){return Array.isArray(v)?v:[];}
function parse(v){
  if(v && typeof v==='object') return v;
  let s=String(v||'').replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
  const a=s.indexOf('{'), b=s.lastIndexOf('}'); if(a>=0&&b>=a) s=s.slice(a,b+1);
  s=s.replace(/,\s*([}\]])/g,'$1');
  try{return JSON.parse(s);}catch{return {};}
}
const ai=parse(raw);
const groups=base.grouped_candidates || {};

function normalizeGroup(key, hasImplication){
  const originals=arr(groups[key]);
  const aiItems=arr(ai.sections?.[key]);
  const byId=new Map(aiItems.map(x=>[txt(x.candidate_id),x]));
  return originals.map((o,idx)=>{
    const x=byId.get(txt(o.candidate_id)) || {};
    return {
      title:txt(x.title || o.title || `후보 ${idx+1}`),
      summary:txt(x.summary || o.summary),
      implication_label:hasImplication ? txt(x.implication_label || '시사점') : '',
      implication:hasImplication ? txt(x.implication || o.implication) : '',
      source_urls:arr(o.source_urls).map(txt).filter(u=>/^https?:\/\//i.test(u)).slice(0,4)
    };
  }).filter(x=>x.title || x.summary);
}
// 섹션별 재생성 모드: base.requested_section이 있으면 그 섹션 하나만 정리해서
// 최소한의 응답(success/section/items)만 반환한다 — 프론트가 이 섹션 배열 하나만
// 갈아끼우면 되므로, 다른 섹션·issue_title·executive_brief는 건드리지 않는다.
if (base.requested_section) {
  const items = normalizeGroup(base.requested_section, true);
  const result = { success:true, mode:'SECTION_REGEN', section: base.requested_section, items };
  if (base.requested_section === 'people_culture') {
    result.people_culture_view = txt(ai.people_culture_view);
  }
  return [{json: result}];
}

const sections={
  client_watch:normalizeGroup('client_watch',true),
  research_on_insight:normalizeGroup('research_on_insight',true),
  business_work:normalizeGroup('business_work',true),
  people_culture:normalizeGroup('people_culture',true),
  people_culture_view:txt(ai.people_culture_view)
};
const newsletter={
  newsletter_title:'Research On Weekly',
  issue_title:txt(ai.issue_title || `${base.period_start} ~ ${base.period_end} 주간 브리핑`),
  period:`${base.period_start} ~ ${base.period_end}`,
  executive_brief:{
    headline:txt(ai.executive_brief?.headline || '이번 주 후보 자료 검토'),
    summary:txt(ai.executive_brief?.summary || '섹션별 후보를 검토하고 최종 발송 항목을 남겨주세요.')
  },
  sections,
  editor_note:txt(ai.editor_note || 'Human in the loop 후보 초안')
};
return [{json:{
  success:true, mode:'HUMAN_REVIEW', issue_id:base.issue_id,
  generated_at:base.generated_at, period_start:base.period_start, period_end:base.period_end,
  candidate_count:base.candidate_count, newsletter
}}];

// 웹에서 관리자가 승인한 뉴스레터를 검증하고 예약 데이터로 정규화
const data=$json.body || $json;
const input=data.newsletter || {};
function txt(v){return v===null||v===undefined?'':String(v).trim();}
function arr(v){return Array.isArray(v)?v:[];}
function safeUrls(v){return arr(v).map(txt).filter(u=>/^https?:\/\//i.test(u)).slice(0,4);}
function cleanItem(x,hasImplication){
  return {
    title:txt(x?.title), summary:txt(x?.summary),
    implication_label:hasImplication?txt(x?.implication_label||'시사점'):'',
    implication:hasImplication?txt(x?.implication):'',
    source_urls:safeUrls(x?.source_urls)
  };
}
const warnings=[];
// 웹 화면(HITL 검토)에서 관리자가 섹션별로 남겨둔 항목을 '전부' 예약한다.
// 한 섹션에 비정상적으로 많은 항목이 남아있을 경우를 대비해 섹션당 최대 6개(웹 화면의 최대 노출 개수와 동일)로만 안전장치를 둔다.
const MAX_PER_SECTION=6;
function selectItems(key,hasImplication){
  const valid=arr(input.sections?.[key]).map(x=>cleanItem(x,hasImplication)).filter(x=>x.title||x.summary);
  if(valid.length>MAX_PER_SECTION) warnings.push(`${key}: ${valid.length}개 중 상위 ${MAX_PER_SECTION}개만 발송에 포함했습니다.`);
  return valid.slice(0,MAX_PER_SECTION);
}
const sections={
  client_watch:selectItems('client_watch',true),
  research_on_insight:selectItems('research_on_insight',true),
  business_work:selectItems('business_work',true),
  people_culture:selectItems('people_culture',true),
  people_culture_view:txt(input.sections?.people_culture_view)
};
const selectedCount=['client_watch','research_on_insight','business_work','people_culture'].reduce((s,k)=>s+sections[k].length,0);
if(!selectedCount) throw new Error('최종 발송 항목이 없습니다. 섹션별로 최소 1개 후보를 남겨주세요.');

const now=new Date();
// 다음(오늘 포함) 월요일 09:00 KST를 UTC ISO로 계산 — 월요일 08시 수집 → 09시 발송 주기에 맞춤
const kstNow=new Date(now.getTime()+9*3600000);
const day=kstNow.getUTCDay();
const daysUntilMonday=(1-day+7)%7;
const targetUtcMs=Date.UTC(kstNow.getUTCFullYear(),kstNow.getUTCMonth(),kstNow.getUTCDate()+daysUntilMonday,9,0,0)-9*3600000;
const scheduledFor=new Date(targetUtcMs).toISOString();
const period=txt(input.period);
const periodEnd=txt(data.period_end || input.period_end || (period.match(/(20\d{2}-\d{2}-\d{2})\s*$/)||[])[1] || now.toISOString().slice(0,10));
const periodStart=txt((period.match(/^(20\d{2}-\d{2}-\d{2})/)||[])[1]);
const newsletter={
  newsletter_title:'Research On Weekly',
  issue_title:txt(input.issue_title || `${periodEnd} 주간 브리핑`),
  period:period || `${periodStart} ~ ${periodEnd}`,
  executive_brief:{headline:txt(input.executive_brief?.headline),summary:txt(input.executive_brief?.summary)},
  sections,
  editor_note:txt(input.editor_note)
};
const recipient=txt(data.recipient || 'bpo.dsplan1@gmail.com');
if(!recipient) throw new Error('수신 이메일이 없습니다.');
return [{json:{
  issue_id:`NLQ-${periodEnd.replace(/-/g,'')}-${Math.random().toString(36).slice(2,7).toUpperCase()}`,
  generated_at:now.toISOString(), queued_at:now.toISOString(), scheduled_for:scheduledFor,
  period_start:periodStart, period_end:periodEnd, recipient,
  selected_count:selectedCount, warnings, newsletter,
  subject:txt(data.subject || `[Research On Weekly] ${newsletter.issue_title}`)
}}];

// =============================================
// 상세 HTML 템플릿 렌더링
// =============================================

const data = $json;
const nl = data.newsletter || {};
const sections = nl.sections || {};

function e(v) {
  return String(v ?? '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#039;');
}
function p(v) {
  return e(v)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g,'<br>');
}
// 인스타그램/틱톡/X/Threads 등은 자기 페이지가 다른 사이트의 iframe 안에 뜨는 걸 서버 차원에서 막는다.
// 이런 도메인만 새 탭으로 열고, 그 외 일반 기사 링크는 관리자 미리보기(iframe) 안에서 그대로 열리게 둔다.
const NEW_TAB_DOMAINS = ['instagram.com','tiktok.com','x.com','twitter.com','threads.net','facebook.com','youtube.com'];
function needsNewTab(url) {
  try { const host = new URL(url).hostname.replace(/^www\./, ''); return NEW_TAB_DOMAINS.some(d => host === d || host.endsWith('.' + d)); }
  catch (e) { return false; }
}
function sourceLinks(urls = []) {
  const safe = Array.isArray(urls) ? urls.filter(Boolean).slice(0,4) : [];
  if (!safe.length) return '';
  const links = safe.map((url, idx) => {
    const attr = needsNewTab(url) ? ' target="_blank" rel="noopener noreferrer"' : '';
    return `<a href="${e(url)}"${attr} style="color:#64748B;text-decoration:underline;">원문 ${idx+1}</a>`;
  }).join('&nbsp;&nbsp;');
  return `<div style="margin-top:13px;font-size:12px;line-height:19px;color:#64748B;">${links}</div>`;
}
function divider() {
  return `<tr><td style="padding:0 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="border-top:1px solid #E5E7EB;font-size:1px;line-height:1px;">&nbsp;</td></tr></table></td></tr>`;
}
function itemBlock(item, culture = false, last = false) {
  const bg = culture ? '#F2F7F4' : '#EEF3FF';
  const labelColor = culture ? '#2F6B4F' : '#274690';
  const textColor = culture ? '#3F5B4C' : '#35415E';
  // 모든 섹션(PEOPLE & CULTURE 포함)에서 시사점이 있으면 박스를 그린다.
  // (예전에는 PEOPLE & CULTURE는 무조건 숨기고 섹션 전체 종합 코멘트만 보여줬으나,
  //  CL4 이상 보직자용으로 항목별 조직 운영 시사점을 반드시 채우도록 프롬프트를 바꿨다.)
  const implicationHtml = item.implication ? `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:16px;border-collapse:collapse;">
      <tr>
        <td style="padding:15px 17px;background-color:${bg};">
          <div style="font-size:12px;line-height:18px;font-weight:bold;color:${labelColor};">${e(item.implication_label || '시사점')}</div>
          <div style="margin-top:5px;font-size:14px;line-height:24px;color:${textColor};">${p(item.implication)}</div>
        </td>
      </tr>
    </table>` : '';
  const block = `
<tr>
  <td style="padding:26px 40px ${last ? '32px' : '26px'};">
    <div style="font-size:20px;line-height:30px;font-weight:bold;color:#111827;">
      ${e(item.title)}
    </div>
    <div style="margin-top:12px;font-size:15px;line-height:26px;color:#3F4652;">
      ${p(item.summary)}
    </div>
    ${implicationHtml}
    ${sourceLinks(item.source_urls)}
  </td>
</tr>`;
  return block + (last ? '' : divider());
}
function cultureViewBlock(view) {
  if (!view) return '';
  return `
<tr>
  <td style="padding:0 40px 32px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">
      <tr>
        <td style="padding:15px 17px;background-color:#F2F7F4;">
          <div style="font-size:12px;line-height:18px;font-weight:bold;color:#2F6B4F;">종합 코멘트</div>
          <div style="margin-top:5px;font-size:14px;line-height:24px;color:#3F5B4C;">${p(view)}</div>
        </td>
      </tr>
    </table>
  </td>
</tr>`;
}
function sectionBlock(no, code, title, description, items, culture = false, trailingView = '') {
  if (!Array.isArray(items) || !items.length) return '';
  const hasTrailing = culture && !!trailingView;
  const lastIdx = items.length - 1;
  const itemsHtml = items
    .map((x, i) => itemBlock(x, culture, hasTrailing ? false : i === lastIdx))
    .join('');
  const trailingHtml = hasTrailing ? cultureViewBlock(trailingView) : '';
  return `
<tr>
  <td style="padding:26px 40px 12px;background-color:#F8FAFC;border-top:1px solid #E5E7EB;">
    <div style="font-size:12px;line-height:18px;letter-spacing:1.2px;font-weight:bold;color:#274690;">${no} · ${e(code)}</div>
    <div style="margin-top:7px;font-size:22px;line-height:32px;font-weight:bold;color:#111827;">${e(title)}</div>
    <div style="margin-top:8px;font-size:14px;line-height:23px;color:#6B7280;">${e(description)}</div>
  </td>
</tr>
${itemsHtml}${trailingHtml}`;
}

const sectionHtml = [
  sectionBlock('01','CLIENT WATCH','주요 클라이언트와 고객 산업 동향',
    '핵심 고객사의 사업·조직·AI·운영 변화를 중심으로 정리했습니다.',
    sections.client_watch || [], false),
  sectionBlock('02','RESEARCH ON INSIGHT','지난주 내부 리서치에서 발견한 핵심 흐름',
    '사용자들이 직접 수행한 리서치에서 반복적으로 나타난 관심사를 정리했습니다.',
    sections.research_on_insight || [], false),
  sectionBlock('03','BUSINESS & WORK','BPO·AI·조직 운영의 주요 변화',
    '본부 사업과 운영에 영향을 줄 수 있는 외부 변화를 정리했습니다.',
    sections.business_work || [], false),
  sectionBlock('04','PEOPLE & CULTURE','요즘 구성원은 무엇에 반응하는가',
    '젊은 세대의 행동과 가치관을 조직 운영 관점에서 해석했습니다.',
    sections.people_culture || [], true, sections.people_culture_view || '')
].join('');

const subject = `[Research On Weekly] ${nl.issue_title || ''}`;

const html = `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${e(subject)}</title>
</head>
<body style="margin:0;padding:0;background-color:#F3F4F6;font-family:Arial,'Apple SD Gothic Neo','Noto Sans KR',sans-serif;color:#111827;word-break:keep-all;overflow-wrap:break-word;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;line-height:1px;font-size:1px;">
    클라이언트 동향, 내부 리서치 인사이트, BPO·AI 변화, 구성원 문화 트렌드를 정리했습니다.
  </div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;margin:0;padding:0;background-color:#F3F4F6;border-collapse:collapse;">
    <tr>
      <td align="center" style="padding:24px 12px;">
        <table role="presentation" width="680" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:680px;background-color:#FFFFFF;border-collapse:collapse;">
          <tr>
            <td style="padding:34px 40px 30px;background-color:#111827;">
              <div style="font-size:12px;line-height:18px;letter-spacing:1.4px;font-weight:bold;color:#AAB4C4;">RESEARCH ON WEEKLY</div>
              <div style="margin-top:12px;font-size:30px;line-height:41px;font-weight:bold;color:#FFFFFF;">${e(nl.issue_title)}</div>
              <div style="margin-top:14px;font-size:13px;line-height:20px;color:#C9D1DD;">${e(nl.period)}</div>
            </td>
          </tr>

          <tr>
            <td style="padding:34px 40px 30px;">
              <div style="font-size:12px;line-height:18px;letter-spacing:1.2px;font-weight:bold;color:#274690;">EXECUTIVE BRIEF</div>
              <div style="margin-top:10px;font-size:23px;line-height:34px;font-weight:bold;color:#111827;">${e(nl.executive_brief?.headline || '')}</div>
              <div style="margin-top:14px;font-size:15px;line-height:26px;color:#3F4652;">${p(nl.executive_brief?.summary || '')}</div>
            </td>
          </tr>

          ${sectionHtml}

          <tr>
            <td style="padding:28px 40px;background-color:#111827;">
              <div style="font-size:13px;line-height:20px;font-weight:bold;color:#FFFFFF;">Research On</div>
              <div style="margin-top:8px;font-size:12px;line-height:20px;color:#AAB4C4;">
                본 뉴스레터는 내부 리서치 결과와 뉴스레터 전용 모니터링 자료를 바탕으로 작성되었습니다.
              </div>
              <div style="margin-top:12px;font-size:11px;line-height:18px;color:#7F8A9B;">
                AI가 생성한 시사점은 제공된 자료를 기반으로 한 해석이며, 주요 의사결정 전 원문 확인이 필요합니다.
              </div>
              <div style="margin-top:14px;font-size:11px;line-height:18px;color:#7F8A9B;">
                더 이상 뉴스레터를 받고 싶지 않으신가요? <a href="__UNSUB_URL__" style="color:#AAB4C4;text-decoration:underline;">구독 해지</a>
              </div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

return [{
  json: {
    issue_id: data.issue_id,
    generated_at: data.generated_at,
    period_start: data.period_start,
    period_end: data.period_end,
    status: 'QUEUED',
    subject: data.subject || subject,
    issue_title: nl.issue_title,
    research_count: data.selected_count,
    newsletter_json: {
      newsletter: nl,
      delivery: {
        recipient: data.recipient,
        queued_at: data.queued_at,
        scheduled_for: data.scheduled_for,
        warnings: data.warnings || []
      }
    },
    newsletter_html: html,
    editor_note: nl.editor_note || '',
    recipient: data.recipient,
    scheduled_for: data.scheduled_for,
    selected_count: data.selected_count,
    warnings: data.warnings || []
  }
}];

const q=$('B2. Code - 승인본 HTML 렌더링 + QUEUED 행 생성').first().json;
return [{json:{
  success:true,
  status:'QUEUED',
  message:'관리자 승인본을 발송 대기열에 저장했습니다. 다음 Schedule Trigger 실행 시 발송됩니다.',
  issue_id:q.issue_id,
  subject:q.subject,
  scheduled_for:q.scheduled_for,
  selected_count:q.selected_count,
  warnings:q.warnings || []
}}];

// QUEUED 상태이며 예약시각이 지난 승인본만 발송 대상으로 분리
const rows=$input.all().map(x=>x.json||{});
const now=Date.now();
function txt(v){return v===null||v===undefined?'':String(v).trim();}
function parse(v){try{return v&&typeof v==='object'?v:JSON.parse(v||'{}');}catch{return {};}}
const seen=new Set();
const out=[];
for(const r of rows){
  if(txt(r.status).toUpperCase()!=='QUEUED') continue;
  const issueId=txt(r.issue_id); if(!issueId || seen.has(issueId)) continue;
  const wrap=parse(r.newsletter_json);
  const delivery=wrap.delivery || {};
  const when=new Date(delivery.scheduled_for || r.generated_at || 0).getTime();
  if(Number.isFinite(when) && when>now) continue;
  const html=txt(r.newsletter_html); if(!html) continue;
  seen.add(issueId);
  out.push({json:{
    issue_id:issueId,
    generated_at:txt(r.generated_at),
    period_start:txt(r.period_start), period_end:txt(r.period_end),
    subject:txt(r.subject), issue_title:txt(r.issue_title),
    newsletter_html:html, newsletter_json:txt(r.newsletter_json),
    editor_note:txt(r.editor_note), research_count:r.research_count,
    recipient:txt(delivery.recipient || 'bpo.dsplan1@gmail.com')
  }});
}
return out;

const q=$('C2D. Code - 발송 대상 × 뉴스레터 조합').item.json;
const failed = !!$json.error;
return [{json:{
  ...q,
  status:'SENT',
  gmail_message_id:$json.id||$json.messageId||'',
  threadId:$json.threadId||'',
  send_success: !failed,
  send_error: failed ? String(($json.error && ($json.error.message||$json.error)) || '알 수 없는 오류') : ''
}}];

// C5B가 Supabase PATCH 응답(return=minimal, 사실상 빈 값)을 그대로 내보내서 $json.issue_id가
// 항상 비어있었음 — C4까지 이름으로 직접 참조해서 실제 issue_id를 가져온다.
