}

if(!row.draft_json){
  return [{json:{ success:true, status: row.status==='generating' ? 'empty' : (row.status||'empty') }}];
}

return [{json:{
  success:true,
  status:'ready',
  stale: row.status === 'generating' && isStale,
  newsletter: row.draft_json,
  period_start: row.period_start,
  period_end: row.period_end,
  generated_at: row.generated_at
}}];
